import{_ as l,c as e,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"泽山咸","description":"周易折中 - 泽山咸","frontmatter":{"title":"泽山咸","description":"周易折中 - 泽山咸"},"headers":[],"relativePath":"zh/classics/zhezhong/037.md","filePath":"zh/classics/zhezhong/037.md"}'),h={name:"zh/classics/zhezhong/037.md"};function p(n,a,d,t,s,o){return i(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="泽山咸" tabindex="-1">泽山咸 <a class="header-anchor" href="#泽山咸" aria-label="Permalink to “泽山咸”">​</a></h1><h3 id="程传" tabindex="-1">程传 <a class="header-anchor" href="#程传" aria-label="Permalink to “程传”">​</a></h3><p>咸序卦：“有天地，然后有万物；有万物，然后有男女；有男女，然后有夫妇；有夫妇，然后有父子；有父子，然后有君臣；有君臣，然后有上下；有上下，然后礼义有所错。”天地，万物之本。夫妇，人伦之始。所以上经首《乾》、《坤》，下经首《咸》继以《恒》也。天地二物，故二卦分为天地之道。男女交合而成夫妇，故《咸》与《恒》皆二体合为夫妇之义。咸，感也，以说为主。恒，常也，以正为本。而说之道自有正也，正之道固有说焉。巽而动，刚柔皆应，说也。《咸》之为卦，兑上艮下，少女少男也。男女相感之深，莫如少者，故二少为《咸》也。艮体笃实，止为诚悫之义。男女笃实以下交，女心说而上应，男感之先也。男先以诚感，则女说而应也。</p><h3 id="集说" tabindex="-1">集说 <a class="header-anchor" href="#集说" aria-label="Permalink to “集说”">​</a></h3><ul><li>邱氏富国曰：《感》，二少相交者，夫妇之始也，所以论交感之情，故以男下女为象。男下于女，婚姻之道成矣。恒二长相承者，夫妇之终也，所以论处家之道。故以男尊女卑为象，女下于男，居室之伦正矣。损虽二少，而男不下女，则咸感之义微，益虽二长，而女居男上，则恒久之义悖。此下经所以不首《损》、《益》而首《咸》、《恒》与？</li></ul><p>咸：亨，利贞，取女吉。</p><h3 id="本义" tabindex="-1">本义 <a class="header-anchor" href="#本义" aria-label="Permalink to “本义”">​</a></h3><p>咸，交感也。兑柔在上，艮刚在下，而交相感应。又艮止则感之专，兑说则应之至。又艮以少男下于兑之少女，男先于女，得男女之正，婚姻之时，故其卦为咸。其占亨而利贞，取女则吉。盖感有必通之理。</p><p>然不以贞，则失其亨，而所为皆凶矣。</p><h3 id="程传-1" tabindex="-1">程传 <a class="header-anchor" href="#程传-1" aria-label="Permalink to “程传”">​</a></h3><p>咸，感也。不曰感者，咸有皆义，男女交相感也。物之相感，莫如男女，而少复甚焉。凡君臣上下，以至万物，皆有相感之道。物之相感，则有亨通之理。君臣能相感，则君臣之道通；上下能相感，则上下之志通；以至父子、夫妇、亲戚朋友，皆情意相感，则和顺而亨通。事物皆然，故咸有亨之理也。利贞，相感之道，利在于正也。不以正，则入于恶矣。如夫妇之以淫姣，君臣之以媚说，上下之以邪僻，皆相感之不以正也。取女吉，以卦才言也。卦有柔上刚下二气感应相与，止而说，男下女之义。以此义取女，则得正而吉也。</p><h3 id="集说-1" tabindex="-1">集说 <a class="header-anchor" href="#集说-1" aria-label="Permalink to “集说”">​</a></h3><ul><li>胡氏炳文曰：咸，感也。不曰感而曰咸，咸皆也， 无心之感也 。无心于感者，无所不通也。感则必通，而利在于正。汎言感之道如此，取女吉，专言取女者当如是也。</li></ul><p>象曰：山上有泽，咸；君子以虚受人</p><h3 id="本义-1" tabindex="-1">本义 <a class="header-anchor" href="#本义-1" aria-label="Permalink to “本义”">​</a></h3><p>山上有泽，以虚而通也。</p><h3 id="程传-2" tabindex="-1">程传 <a class="header-anchor" href="#程传-2" aria-label="Permalink to “程传”">​</a></h3><p>泽性润下，土性受润泽。在山上而其渐润通彻，是二物之气相感通也。君子观山泽通气之象，而虚其中以受于人。夫人中虚，则能受；实则不能入矣。虚中者无我也。中无私主，则无感不通。以量而容之，择合而受之，非圣人有感必通之道也。</p><h3 id="集说-2" tabindex="-1">集说 <a class="header-anchor" href="#集说-2" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>崔氏憬曰：山高而降，泽下而升，山泽通气，咸之象也。</p></li><li><p>吕氏大临曰：泽居下而山居高，然山能出云而致雨者，山内虚而泽气通也。故君子居物之上，物情交感者，亦以虚受也。</p></li><li><p>郭氏雍曰：唯虚故受，受故能感。不能感者，以不能受故也；不能受者，以不能虚故也。</p></li><li><p>胡氏炳文曰：以虚受人，无心之感也。</p></li><li><p>陈氏琛曰：山上有泽，泽以润而感乎山，山以虚而受其感，咸之象也。君子礼之，则虚其心以受人之感焉。盖心无私主，有感皆通。若有一豪私意自蔽，则先入者为主，而感应之机窒矣。虽有所受，未必其所当受，而所当受者反以为不合而不之受矣。</p></li><li><p>何氏楷曰：六爻之中，一言思，三言志。思何可废？而至于朋从，则非虚；志何可无？而末而外而随人，则非虚。极而言之，天地以虚而感物，圣人以虚而感人心。三才之道，尽于是矣。</p></li><li><p>吴氏曰：愼曰：虚者，咸之贞也。天地之常以其心普万物而无心，圣人之常以其情顺万事而无情，者虚而已。君子之学，廓然大公，物来顺应，所谓以虚受人也。</p></li></ul><p>彖曰：咸，感也</p><h3 id="本义-2" tabindex="-1">本义 <a class="header-anchor" href="#本义-2" aria-label="Permalink to “本义”">​</a></h3><p>释卦名义。</p><h3 id="集说-3" tabindex="-1">集说 <a class="header-anchor" href="#集说-3" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>刘氏牧曰：卦以咸名，而彖传以感释其义者，圣人之旨欲明感物之无心也。</p></li><li><p>张子曰：万物本一，故一能合异。以其能合异，故谓之感。若非有异，则无合。天地乾坤，阴阳也，二端故有感。本一故能合。</p></li><li><p>丘氏富国曰：咸者，感也。所以感者，心也。无心者不能感，故咸加心而为感。有心于感者，亦不能咸感，故感去心而为咸。咸皆也，唯无容心于感，然后无所不感。圣人以咸名卦，而彖以感释之，所以互明其旨也。</p></li><li><p>王氏应麟曰：咸之感无心，感以虚也；兑之说无言，说以诚也。</p></li></ul><p>柔上而刚下，二气感应以相与，止而说，男下女，是以亨利贞，取女吉也</p><h3 id="本义-3" tabindex="-1">本义 <a class="header-anchor" href="#本义-3" aria-label="Permalink to “本义”">​</a></h3><p>以卦体、卦德、卦象释卦辞，或以卦变言柔上刚下之义。曰咸自旅来，柔上居六，刚下居五也，亦通。</p><h3 id="程传-3" tabindex="-1">程传 <a class="header-anchor" href="#程传-3" aria-label="Permalink to “程传”">​</a></h3><p>咸之义感也。在卦则柔爻上而刚爻下。柔上变刚而成兑，刚下变柔而成艮。阴阳相交为男女交感之义，又兑女在上，艮男居下，亦柔上刚下也。阴阳二气相感相应而和合，是相与也。止而说，止于说为坚悫之意，艮止于下，笃诚相下也；兑说于上，和说相应也。以男下女，和之至也。相感之道如此，是以能亨通而得正。取女如是，则吉也。卦才如此，大率感道利于正也。</p><h3 id="集说-4" tabindex="-1">集说 <a class="header-anchor" href="#集说-4" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏肃曰：山泽以气通，男女以礼感。男下女，初婚之所以为礼，取女之所以为吉也。</p></li><li><p>冯氏当可曰：柔上刚下，感应相与，所以为亨；止而说，所以利贞；男下女，所以取女吉也。</p></li><li><p>王氏申子曰：止而说者，谓艮止不动而意气自相和说，乃所谓感。不止而动，则是出于作为，非感也。故六爻皆欲其静。</p></li><li><p>蔡氏清曰：卦体、卦德、卦象三段意，皆归于咸之一字内。而所谓亨利贞取女吉者，义盖从此而出。故本义以通释卦名卦辞。</p></li></ul><p>天地感而万物化生，圣人感人心而天下和平，观其所感，而天地万物之情可见矣</p><h3 id="本义-4" tabindex="-1">本义 <a class="header-anchor" href="#本义-4" aria-label="Permalink to “本义”">​</a></h3><p>极言感通之理。</p><h3 id="程传-4" tabindex="-1">程传 <a class="header-anchor" href="#程传-4" aria-label="Permalink to “程传”">​</a></h3><p>既言男女相感之义，复推极感道以尽天地之理。天地二气交感而化生万物，圣人至诚以感亿兆之心而天下和平。天下之心所以和平，由圣人感之也。观天地交感化生万物之理，与圣人感人心致和平之道，则天地万物之情可见矣。感通之理，知道者默而观之可也。</p><h3 id="集说-5" tabindex="-1">集说 <a class="header-anchor" href="#集说-5" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>张子曰：能通天下之志者为能感人心。圣人同乎人而无我，故和平天下莫盛于感人心。</p></li><li><p>郑氏汝谐曰：天地万物虽异位，其气则一；圣人亿兆虽异势，其诚则一。观其所感，而其情可见者，感生于情也。情出于正，然后知感通之理。</p></li><li><p>张氏清子曰：寂然不动，性也；感而遂通，情也。于其所感而观之，而天地万物之情可得而见矣。</p></li></ul><p>初六：咸其拇</p><h3 id="本义-5" tabindex="-1">本义 <a class="header-anchor" href="#本义-5" aria-label="Permalink to “本义”">​</a></h3><p>拇，足大指也。咸以人身取象，感于最下，咸拇之象也。感之尚浅，欲进未能，故不言吉凶。此卦虽主于感，然六爻皆宜静而不宜动也。</p><h3 id="程传-5" tabindex="-1">程传 <a class="header-anchor" href="#程传-5" aria-label="Permalink to “程传”">​</a></h3><p>初六在下卦之下，与四相感。以微处初，其感未深，岂能动于人？故如人拇之动，未足以进也。拇，足大指。人之相感，有浅深轻重之异，识其时𫝑，则所处不失其宜矣。</p><h3 id="集说-6" tabindex="-1">集说 <a class="header-anchor" href="#集说-6" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>朱子语类问：咸内卦艮止也，何以皆说动？曰：艮虽是止，然咸有交感之义，都是要动，所以都说动。卦体虽说动，然才动便不吉。</p></li><li><p>蔡氏清曰：“咸其拇”，辞意若曰“感以其拇也”。诸爻皆同。</p></li><li><p>又曰：本义云，此卦虽主于感，然六爻皆宜静而不宜动。此即以虚受人之理。大传曰：“寂然不动，感而遂通天下之故。”程子曰：“廓然而大公，物来而顺应。”周子所谓“主静”，朱子所谓“鉴空衡平”，及先儒所谓“无心之感”者，皆谓此也。</p></li></ul><p>象曰：咸其拇，志在外也</p><h3 id="程传-6" tabindex="-1">程传 <a class="header-anchor" href="#程传-6" aria-label="Permalink to “程传”">​</a></h3><p>初志之动，感于四也，故曰在外。志虽动而感未深，如拇之动，未足以进也。</p><h3 id="集说-7" tabindex="-1">集说 <a class="header-anchor" href="#集说-7" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>虞氏翻曰：志在外，谓四也。</p></li><li><p>孔氏颖逹曰：与四相应，所感在外。</p></li><li><p>俞氏琰曰：初与四感应以相与，则志之所之在于外矣。</p></li></ul><p>六二：咸其腓，凶，居吉。</p><h3 id="本义-6" tabindex="-1">本义 <a class="header-anchor" href="#本义-6" aria-label="Permalink to “本义”">​</a></h3><p>腓，足肚也。欲行则先自动，躁妄而不能固守者也。二当其处，又以阴柔不能固守，故取其象。然有中正之德，能居其所，故其占动凶而静吉也。</p><h3 id="程传-7" tabindex="-1">程传 <a class="header-anchor" href="#程传-7" aria-label="Permalink to “程传”">​</a></h3><p>二以阴在下，与五为应，故设咸腓之戒。腓，足肚，行则先动，足乃举之，非如腓之自动也。二若不守道，待上之求而如腓之动，则躁妄自失，所以凶也。安其居而不动，以待上之求，则得进退之道而吉也。二中正之人，以其在咸而应五，故为此戒。复云“居吉”，若安其分，不自动，则吉也。</p><h3 id="集说-8" tabindex="-1">集说 <a class="header-anchor" href="#集说-8" aria-label="Permalink to “集说”">​</a></h3><ul><li>王氏弼曰：咸道转进，离拇升腓。腓，体动躁者也。感物以躁，凶之道也。由躁故凶，居则吉矣。处不乘刚，故可以居而获吉。</li></ul><p>象曰：虽凶居吉，顺不害也</p><h3 id="程传-8" tabindex="-1">程传 <a class="header-anchor" href="#程传-8" aria-label="Permalink to “程传”">​</a></h3><p>二居中得正，所应又中正，其才本善。以其在咸之时，质柔而上应，故戒以先动求君则凶，居以自守则吉。象复明之云：“非戒之不得相感，唯顺理则不害。”谓守道不先动也。</p><h3 id="集说-9" tabindex="-1">集说 <a class="header-anchor" href="#集说-9" aria-label="Permalink to “集说”">​</a></h3><ul><li>顾氏象德曰：虽凶而居则吉者，盖能顺理以为感，不为躁动害也。居非专静，特不妄动而已。</li></ul><p>九三：咸其股，执其随，往吝。</p><h3 id="本义-7" tabindex="-1">本义 <a class="header-anchor" href="#本义-7" aria-label="Permalink to “本义”">​</a></h3><p>股，随足而动，不能自专者也。执者，主当持守之意。下二爻皆欲动者，三亦不能自守而随之往，则吝矣。故其象占如此。</p><h3 id="程传-9" tabindex="-1">程传 <a class="header-anchor" href="#程传-9" aria-label="Permalink to “程传”">​</a></h3><p>九三以阳居刚，有刚阳之才而为主于内，居下之上，是宜自得于正道以感于物。而乃应于上六，阳好上而说阴，上居感说之极，故三感而从之。股者在身之下，足之上，不能自由，随身而动者也，故以为象。言九三不能自主，随物而动，如股然。其所执守者，随于物也。刚阳之才，感于所说而随之，如此而往，可羞吝也。</p><h3 id="集说-10" tabindex="-1">集说 <a class="header-anchor" href="#集说-10" aria-label="Permalink to “集说”">​</a></h3><ul><li>王氏宗传曰：九三处下体之上，所谓股也。三虽艮体，然以阳居阳，又有应在上，非能止也。故曰“咸其股”。夫股随上体而动者也。以刚过之才，不能为主于内，而其所秉执者，在于随上体而动焉，则躁动而失正矣。故曰“往吝”。</li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>执其随，本义以为随下二爻，程传以为随上。然随之为义，取于雁行相从，则以三为随四者近是。证之随卦，初刚随二柔，五刚随上柔，可见也。盖四者心位也，心动则形随之。而三直股位，与四相近而相承，故有“咸其股，执其随”之象。证之艮卦，以三为心位，六二亦曰“不拯其随”，可见也。夫心固身之主也，然心动而形辄随之，亦非制外飬中之道。推之人事，则如臣子之诡随容顺皆是也。以三之德不中正，故如此。</p><p>象曰：咸其股，亦不处也；志在随人，所执下也</p><h3 id="本义-8" tabindex="-1">本义 <a class="header-anchor" href="#本义-8" aria-label="Permalink to “本义”">​</a></h3><p>言“亦”者，因前二爻皆欲动而云也。二爻阴躁，其动也宜；九三阳刚，居止之极，宜静而动，可吝之甚也。</p><h3 id="程传-10" tabindex="-1">程传 <a class="header-anchor" href="#程传-10" aria-label="Permalink to “程传”">​</a></h3><p>云“亦”者，盖象辞本不与易相比，自作一处。故诸爻之象辞意有相续者，此言“亦”者承上爻辞也。上云“咸其拇，志在外也；虽凶居吉，顺不害也。”咸其股，亦不处也。前二阴爻皆有感而动，三虽阳爻亦然，故云“亦不处也”。不处谓动也。有阳刚之质而不能自主，志反在于随人，是所操执者卑下之甚也。</p><p>九四：贞吉悔亡，憧憧往来，朋从尔思。</p><h3 id="本义-9" tabindex="-1">本义 <a class="header-anchor" href="#本义-9" aria-label="Permalink to “本义”">​</a></h3><p>九四居股之上、脢之下，又当三阳之中心，咸之主也。心之感物，当正而固，乃得其理。今九四乃以阳居阴，为失其正而不能固，故因占设戒。以为能正而固，则吉而悔亡。若憧憧往来，不能正固而累于私感，则其朋类从之，不复能及远矣。</p><h3 id="程传-11" tabindex="-1">程传 <a class="header-anchor" href="#程传-11" aria-label="Permalink to “程传”">​</a></h3><p>感者，人之动也，故皆就人身取象。拇取在下而动之微，腓取先动，股取其随。九四无所取，直言感之道，不言咸。其心感，乃心也。四在中而居上，当心之位，故为感之主而言感之道。贞正则吉而悔亡。感不以正，则有悔也。又四说体居阴而应初，故戒于贞。感之道，无所不通，有所私系，则害于感通，乃有悔也。圣人感天下之心，如寒暑雨旸，无不通无不应者，亦贞而已矣。贞者，虚中无我之谓也。憧憧往来，朋从尔思。夫贞一则所感无不通，若往来憧憧然，用其私心以感物，则思之所及者，有能感而动，所不及者不能感也。是其朋类，则从其思也。以有系之私心既主于一隅一事，岂能廓然无所不通乎？</p><p>系辞曰：“天下何思何虑？天下同归而殊涂，一致而百虑。天下何思何虑？”夫子因咸极论感通之道。夫以思虑之私心感物，所感狭矣。天下之理一也，涂虽殊而其归则同，虑虽百而其致则一。虽物有万殊，事有万变，统之以一，则无能违也。故贞其意，则穷天下无不感通焉。故曰“天下何思何虑”。用其思虑之私心，岂能无所不感也？日往则月来，月往则日来，日月相推而明生焉。寒往则暑来，暑往则寒来，寒暑相推而岁成焉。往者屈也，来者信也，屈信相感而利生焉。此以往来屈信，明感应之理。屈则有信，信则有屈，所谓感应也。故日月相推而明生，寒暑相推而岁成，功用由是而成。故曰“屈信相感而利生焉”。感动也，有感必有应。凡有动皆为感，感则必有应，所应复为感，感复有应，所以不已也。尺蠖之屈以求信也，龙蛇之蛰以存身也，精义入神以致用也，利用安身以崇德也。过此以往，未之或知也。前云屈信之理矣，复取物以明之。尺蠖之行，先屈而后信，盖不屈则无信，信而后有屈。观尺蠖，则知感应之理矣。龙蛇之藏，所以存息其身而后能奋迅也，不蛰则不能奋矣。动息相感，乃屈信也。君子潜心精微之义，入于神妙，所以致其用也。潜心精微，积也；致用，施也。积与施，乃屈信也。利用安身以崇德也，承上文致用而言。利其施用，安处其身，所以崇大其德业也。所为合理，则事正而身安。圣人能事尽于此矣。故云“过此以往，未之或知也”。穷神知化，德之盛也。既云“过此以往，未之或知”，更以此语终之，云“穷极至神之妙，知化育之道德之至盛也，无加于此矣”。</p><h3 id="集说-11" tabindex="-1">集说 <a class="header-anchor" href="#集说-11" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>程子曰：天地之常，以其心普万物而无心；圣人之常，以其情顺万事而无情。故君子之学，莫若廓然而大公，物来而顺应。故曰“贞吉悔亡，憧憧往来，朋从尔思”。</p></li><li><p>杨氏时曰：九四，脢之下，股之上，心之位也。不言心，心无不该，不可以位言也。</p></li><li><p>朱子语类：问：咸九四，“传说虚心贞一，处全似敬”。 曰：“盖尝有此语，曰‘敬，心之贞也’”。 问：“憧憧往来，朋从尔思”，莫是此感彼应，憧憧是添一个心否？ 曰：“往来固是感应，憧憧是一心方欲感他，一心又欲他来应，如‘正其义便欲谋其利，明其道便欲计其功’。又如‘赤子入井之时，此心方怵惕要去救他，又欲他父母道我好’。这便是憧憧之病”。 又云：“憧憧往来，朋从尔思”。圣人未尝不教人思，只是不可憧憧。这便是私了。感应自有个自然底道理，何必思他？若是义理，则不可不思。 问：“往来”是心中憧憧然往来，犹言“往来于怀”否？ 曰：“非也”。 又问：“是憧憧于往来之闲否？” 曰：“亦非也。只是对那日往则月来底说。那个是自然之往来，此憧憧者是加私意不好底往来。憧憧只是加一个忙迫底心，不能顺自然之理。方往时又便要来，方来时又便要往，只是一个忙”。 问：“憧憧往来”如霸者以私心感人，便要人应；“自然往来”如王者，我感之也无心，而感其应我也无心而应，周遍公溥，无所私系。 曰：“也是如此”。又 问：“此以私而感彼，非以私而应，只是应之者有限量否？” 曰：“也是以私而应，如我以私惠及人少，闲被我之惠者则以我为恩，不被我之惠者则不以我为恩矣”。</p></li><li><p>问：咸九四，“传说虚心贞一，处全似敬”。 曰：“盖尝有此语，曰‘敬，心之贞也’”。</p></li><li><p>问：“憧憧往来，朋从尔思”，莫是此感彼应，憧憧是添一个心否？ 曰：“往来固是感应，憧憧是一心方欲感他，一心又欲他来应，如‘正其义便欲谋其利，明其道便欲计其功’。又如‘赤子入井之时，此心方怵惕要去救他，又欲他父母道我好’。这便是憧憧之病”。</p></li><li><p>又云：“憧憧往来，朋从尔思”。圣人未尝不教人思，只是不可憧憧。这便是私了。感应自有个自然底道理，何必思他？若是义理，则不可不思。</p></li><li><p>问：“往来”是心中憧憧然往来，犹言“往来于怀”否？ 曰：“非也”。</p></li><li><p>又问：“是憧憧于往来之闲否？” 曰：“亦非也。只是对那日往则月来底说。那个是自然之往来，此憧憧者是加私意不好底往来。憧憧只是加一个忙迫底心，不能顺自然之理。方往时又便要来，方来时又便要往，只是一个忙”。</p></li><li><p>问：“憧憧往来”如霸者以私心感人，便要人应；“自然往来”如王者，我感之也无心，而感其应我也无心而应，周遍公溥，无所私系。 曰：“也是如此”。又</p></li><li><p>问：“此以私而感彼，非以私而应，只是应之者有限量否？” 曰：“也是以私而应，如我以私惠及人少，闲被我之惠者则以我为恩，不被我之惠者则不以我为恩矣”。</p></li><li><p>胡氏炳文曰：“寂然不动，心之体；感而遂通，心之用。憧憧往来，已失其寂然不动之体，安能感而遂通天下之故？贞吉悔亡，无心之感也，何思何虑之有？憧憧往来，私矣”。</p></li><li><p>林氏希元曰：以“憧憧往来”反观九四之贞，只是往来付之无心尔。盖尽吾所感之道，而人之应与否皆所不计也。此便是正而固。“憧憧往来”是把个往来放在心上，切切然不能放下，故曰“何思何虑”，言其不消如此。 又曰：“贞者，施己之感不必人之应也。惟不必人之应，则不私己之感，其应者亦感，其不应者亦感，无一人之不感，亦无一人之不应，故吉而悔亡”。“憧憧往来者，施己之感必人之应也。惟必人之应，则私己之感，应者则感，不应者则不感，而其应之亦惟其感者即应，不感者则不应矣。故‘朋从尔思’。盖‘憧憧往来’是思也，‘朋’则思之所及者。以其思之所及，故从而目之曰‘朋’，犹云‘朋党’也”。</p></li><li><p>又曰：“贞者，施己之感不必人之应也。惟不必人之应，则不私己之感，其应者亦感，其不应者亦感，无一人之不感，亦无一人之不应，故吉而悔亡”。“憧憧往来者，施己之感必人之应也。惟必人之应，则私己之感，应者则感，不应者则不感，而其应之亦惟其感者即应，不感者则不应矣。故‘朋从尔思’。盖‘憧憧往来’是思也，‘朋’则思之所及者。以其思之所及，故从而目之曰‘朋’，犹云‘朋党’也”。</p></li></ul><p>象曰：贞吉悔亡，未感害也；憧憧往来，未光大也</p><h3 id="本义-10" tabindex="-1">本义 <a class="header-anchor" href="#本义-10" aria-label="Permalink to “本义”">​</a></h3><p>感害，言不正而感则有害也。</p><h3 id="程传-12" tabindex="-1">程传 <a class="header-anchor" href="#程传-12" aria-label="Permalink to “程传”">​</a></h3><p>贞则吉而悔亡，未为私感所害也。系私应则害于感矣。憧憧往来，以私心相感，感之道狭矣，故云“未光大也”。</p><h3 id="集说-12" tabindex="-1">集说 <a class="header-anchor" href="#集说-12" aria-label="Permalink to “集说”">​</a></h3><ul><li>陆氏九渊曰：咸九四一爻，圣人以其当心之位，其言感通为尤至。曰“贞吉悔亡”，而象以为“未感害也”，盖未为私感所害，则心之本然无适而不正，无感而不通。曰“憧憧往来，朋从尔思”，而象以为“未光大也”，盖憧憧往来之私心，其所感必狭，从其思者独其私朋而已。圣人之洗心，其诸以涤去憧憧往来之私，而全其本然之正也。与此所以退藏于密，而能同乎民，交乎物，而不堕于胶焉溺焉之一偏者也。</li></ul><p>九五：咸其脢，无悔。</p><h3 id="本义-11" tabindex="-1">本义 <a class="header-anchor" href="#本义-11" aria-label="Permalink to “本义”">​</a></h3><p>脢，背肉也，在心上而相背，不能感物而无私系。九五适当其处，故取其象，而戒占者以能如是，则虽不能感物，而亦可以无悔也。</p><h3 id="程传-13" tabindex="-1">程传 <a class="header-anchor" href="#程传-13" aria-label="Permalink to “程传”">​</a></h3><p>九居尊位，当以至诚感天下，而应二比上。若系二而说上，则偏私浅狭，非人君之道。岂能感天下乎？脢，背肉也，与心相背，而所不见也。言能背其私心，感非其所见，而说者，则得人君感天下之正而无悔也。</p><h3 id="集说-13" tabindex="-1">集说 <a class="header-anchor" href="#集说-13" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>孔氏颖达曰：马融云：“脢，背也。”郑康成云：“脢，脊肉也。”王肃云：“脢在背而夹脊。”诸说不同，大体皆在心上。</p></li><li><p>王氏宗传曰：上六处咸之末，以口舌为容悦之道。五或以其近己也，比而说之。脢，背肉也，与心相背者也。戒之使背其心之所向，则无亲狎之悔矣。</p></li></ul><p>象曰：咸其脢，志末也</p><h3 id="本义-12" tabindex="-1">本义 <a class="header-anchor" href="#本义-12" aria-label="Permalink to “本义”">​</a></h3><p>志末，谓不能感物。</p><h3 id="程传-14" tabindex="-1">程传 <a class="header-anchor" href="#程传-14" aria-label="Permalink to “程传”">​</a></h3><p>戒使背其心而咸脢者，为其存心浅末，系二而说上，感于私欲也。</p><h3 id="集说-14" tabindex="-1">集说 <a class="header-anchor" href="#集说-14" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>李氏鼎祚曰：末犹上也。五比于上，故咸其脢，志末者谓五志感于上也。</p></li><li><p>朱氏震曰：卦以初为本，上为末。</p></li><li><p>王氏宗传曰：谓五有咸其脢之象者，以其志意之所向在于一卦之末，故欲咸其脢以背去之也。</p></li><li><p>何氏楷曰：谓五志在与上相感也。系辞曰：“其初难知，其上易知。”本末也。《大过》彖传“本末弱”，末指上六可知矣。</p></li></ul><p>上六：咸其辅颊舌</p><h3 id="本义-13" tabindex="-1">本义 <a class="header-anchor" href="#本义-13" aria-label="Permalink to “本义”">​</a></h3><p>辅、颊、舌，皆所以言者，而在身之上。上六以阴居说之终，处咸之极，感人以言而无其实，又兑为口舌，故其象如此。凶咎可知。</p><h3 id="程传-15" tabindex="-1">程传 <a class="header-anchor" href="#程传-15" aria-label="Permalink to “程传”">​</a></h3><p>上阴柔而说，体为说之主，又居感之极，是其欲感物之极也。故不能以至诚感物，而发见于口舌之间，小人女子之常态也，岂能动于人乎？不直云口，而云辅颊舌，亦犹今人谓口过曰唇吻、曰颊舌也。辅颊舌皆所用以言也。</p><h3 id="集说-15" tabindex="-1">集说 <a class="header-anchor" href="#集说-15" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏弼曰：辅颊舌者，所以为语之具也。咸其辅颊舌，则滕口说也。憧憧往来，犹未光大，况在滕口，薄可知也。</p></li><li><p>郭氏忠孝曰：《易》称近取诸身，独咸、艮二卦言之为详，而其成终有特异。岂非咸极于说，艮终于止耶？观“艮其辅，言有序”为可知矣。</p></li></ul><p>象曰：咸其辅颊舌，滕口说也</p><h3 id="本义-14" tabindex="-1">本义 <a class="header-anchor" href="#本义-14" aria-label="Permalink to “本义”">​</a></h3><p>滕，滕通用。</p><h3 id="程传-16" tabindex="-1">程传 <a class="header-anchor" href="#程传-16" aria-label="Permalink to “程传”">​</a></h3><p>唯至诚为能感人，乃以柔说腾扬于口舌，言说岂能感于人乎？</p><h3 id="集说-16" tabindex="-1">集说 <a class="header-anchor" href="#集说-16" aria-label="Permalink to “集说”">​</a></h3><ul><li>王氏弼曰：咸道转末，故在口舌言语而已。</li></ul><p>总论</p><ul><li><p>郑氏汝谐曰：卦言感应之理，六爻皆不纯乎吉，何也？卦合而言之，爻析而言之。天地感而万物化生，圣人感人心而天下和平，咸之全也。六爻之所感不同，咸之偏也。自初至上，皆以人身为象，囿于有我，安能无所不感乎？</p></li><li><p>易氏祓曰：咸，感也。感以心为主，而偏体皆所感之一。初咸其拇，二咸其腓，三咸其股，五咸其脢，上咸其辅颊舌，皆感其偏体者也。所感出于心，故皆以“咸”字明之。九四在上下之闲，其位在心，故不言咸而言所感之道。</p></li><li><p>丘氏富国曰：咸六爻以身取象，上卦象上体，下卦象下体。初在下体之下为拇，二在下体之中为腓，三在下体之上为股，此下卦三爻之序也。四在上体之下为心，五在上体之中为脢，上在上体之上为口，此上卦三爻之序也。</p></li><li><p>龚氏焕曰：咸以人身取象，与艮卦相类。但咸感，艮止，感者动，而止者静。故咸诸爻不如艮吉多而凶少。</p></li></ul>',122)])])}const m=l(h,[["render",p]]);export{b as __pageData,m as default};
